parameters.jsCode:
// Current lead from Normalize Lead Data
const currentLead = $('Normalize Lead Data').first().json;

// All existing leads from Google Sheets
const existingLeads = $('Load Existing Leads').all();

let duplicate = false;

for (const lead of existingLeads) {

    const row = lead.json;

    if (
        row.Client_Email?.toLowerCase() === currentLead.email?.toLowerCase() &&
        row.Job_Title?.toLowerCase() === currentLead.project_title?.toLowerCase()
    ) {
        duplicate = true;
        break;
    }
}

return [
{
    json: {
        ...currentLead,
        duplicate_found: duplicate
    }
}
];

// Get AI response
let text = $json.text || $json.output || $json.response || "";

// Remove markdown fences if present
text = text.replace(/```json/g, "")
           .replace(/```/g, "")
           .trim();

try {
    const ai = JSON.parse(text);

    return [{
        json: {
            ...$('Normalize Lead Data').first().json,
            ...ai
        }
    }];
} catch (err) {
    throw new Error("Invalid AI JSON:\n" + text);
}
